import Link from "next/link";
import type { Prisma } from "@prisma/client";

import { db } from "@/lib/db";
import { exigirPermiso } from "@/lib/auth";
import { puede } from "@/lib/rbac";
import { pesos } from "@/lib/dinero";
import { Titulo, Tarjeta, Insignia, Vacio } from "@/components/ui";

export const metadata = { title: "Clientas" };

export default async function PaginaClientas({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; grupo?: string }>;
}) {
  const sesion = await exigirPermiso("clientas.ver");
  const { q = "", grupo = "" } = await searchParams;
  const puedeCrear = puede(sesion.usuario.rol, "clientas.crear");

  const where: Prisma.ClienteWhereInput = {
    ...(grupo ? { grupoId: grupo } : {}),
    ...(q.trim()
      ? {
          OR: [
            { nombre: { contains: q.trim(), mode: "insensitive" as const } },
            { avalNombre: { contains: q.trim(), mode: "insensitive" as const } },
            { telefono: { contains: q.replace(/\D/g, "") || "�" } },
          ],
        }
      : {}),
  };

  const [clientas, grupos] = await Promise.all([
    db.cliente.findMany({
      where,
      orderBy: { nombre: "asc" },
      take: 300,
      include: {
        grupo: { select: { id: true, nombre: true } },
        creditos: {
          orderBy: { creadoEn: "desc" },
          select: {
            id: true,
            estado: true,
            montoTotal: true,
            abonos: { select: { montoPagado: true } },
          },
        },
      },
    }),
    db.grupo.findMany({ where: { activo: true }, orderBy: { nombre: "asc" }, select: { id: true, nombre: true } }),
  ]);

  return (
    <>
      <div className="flex flex-wrap items-start justify-between gap-4">
        <Titulo sub="Expediente de cada clienta: datos, aval, historial de créditos y documentos escaneados.">
          Clientas
        </Titulo>
        {puedeCrear ? (
          <Link href="/clientas/nueva" className="btn-primario">
            Nueva clienta
          </Link>
        ) : null}
      </div>

      <form className="mb-5 flex flex-wrap gap-3" action="/clientas">
        <input
          name="q"
          defaultValue={q}
          className="campo max-w-xs flex-1"
          placeholder="Buscar por nombre, aval o teléfono"
          aria-label="Buscar clienta"
        />
        <select name="grupo" defaultValue={grupo} className="campo max-w-56" aria-label="Filtrar por grupo">
          <option value="">Todos los grupos</option>
          {grupos.map((g) => (
            <option key={g.id} value={g.id}>
              {g.nombre}
            </option>
          ))}
        </select>
        <button type="submit" className="btn-secundario">
          Buscar
        </button>
      </form>

      <Tarjeta titulo={`${clientas.length} ${clientas.length === 1 ? "clienta" : "clientas"}`}>
        {clientas.length === 0 ? (
          <Vacio
            accion={
              puedeCrear ? (
                <Link href="/clientas/nueva" className="btn-secundario">
                  Dar de alta la primera
                </Link>
              ) : null
            }
          >
            No se encontraron clientas con esos filtros.
          </Vacio>
        ) : (
          <div className="scroll-suave overflow-x-auto">
            <table className="tabla">
              <thead>
                <tr>
                  <th>Folio</th>
                  <th>Clienta</th>
                  <th>Grupo</th>
                  <th>Aval</th>
                  <th className="text-right">Créditos</th>
                  <th className="text-right">Saldo vigente</th>
                </tr>
              </thead>
              <tbody>
                {clientas.map((c) => {
                  const activo = c.creditos.find((x) => x.estado === "ACTIVO" || x.estado === "VENCIDO");
                  const saldo = activo
                    ? Math.max(0, activo.montoTotal - activo.abonos.reduce((s, a) => s + a.montoPagado, 0))
                    : 0;
                  return (
                    <tr key={c.id}>
                      <td className="tabular-nums text-xs text-tinta/50">
                        {String(c.folio).padStart(4, "0")}
                      </td>
                      <td>
                        <Link href={`/clientas/${c.id}`} className="font-medium text-patrimonio hover:underline">
                          {c.nombre}
                        </Link>
                        {c.telefono ? <p className="text-xs text-tinta/50">{c.telefono}</p> : null}
                      </td>
                      <td className="text-sm">
                        {c.grupo ? (
                          <Insignia tono="verde">{c.grupo.nombre}</Insignia>
                        ) : (
                          <span className="text-tinta/35">Sin grupo</span>
                        )}
                      </td>
                      <td className="text-sm">
                        {c.avalNombre ?? <span className="text-tinta/35">Falta aval</span>}
                      </td>
                      <td className="text-right tabular-nums">{c.creditos.length}</td>
                      <td className="text-right tabular-nums">
                        {activo ? (
                          <span
                            className={
                              activo.estado === "VENCIDO"
                                ? "font-semibold text-riesgo"
                                : "font-medium text-patrimonio"
                            }
                          >
                            {pesos(saldo)}
                          </span>
                        ) : (
                          <span className="text-tinta/35">—</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Tarjeta>
    </>
  );
}
